-- Economics Gen2 Season 2 Tour 5. Versioned hard content, 6 easy/10 medium/4 hard.
-- Does not touch legacy Season 1 and aborts if there is learner history on the target season.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='75s';
DO $tour5$
DECLARE
 d jsonb:='[{"ref":"EC9708:G2:EC9708-G2-T5-T-008","d":"hard","sec":135,"k":"D","en":"In labour market A, demand is Ld=80−2w and supply is Ls=20+w. In market B, demand is Ld=140−4w and supply is Ls=20+2w. Here w is the hourly wage, and all quantities are worker-hours. A nationwide minimum wage of $25 is introduced, with no changes to either curve. What are employment and excess labour supply in the two markets after the law?","ru":"На рынке труда A спрос Ld=80−2w, предложение Ls=20+w. На рынке B спрос Ld=140−4w, предложение Ls=20+2w. Здесь w — почасовая оплата, количества измеряются в человеко-часах. Вводится единая минимальная зарплата $25; кривые не меняются. Каковы занятость и избыток предложения труда в каждом рынке после закона?","uz":"A mehnat bozorida talab Ld=80−2w, taklif Ls=20+w. B bozorida talab Ld=140−4w, taklif Ls=20+2w. w — soatlik ish haqi, miqdor ishchi-soatlarda. Ikki bozorga ham $25 eng kam ish haqi joriy etiladi, egri chiziqlar o‘zgarmaydi. Yangi qonundan keyin bandlik va ortiqcha mehnat taklifi qancha?","options_en":["A employs 45 with 15 excess hours; B employs 70 with 30 excess hours","A employs 30 with no excess; B employs 40 with no excess","A employs 30 with 30 excess; B employs 40 with 15 excess","A employs 30 with 15 excess; B employs 40 with 30 excess"],"options_ru":["A: занято 45, избыток 15 часов; B: занято 70, избыток 30","A: занято 30 без избытка; B: занято 40 без избытка","A: занято 30, избыток 30; B: занято 40, избыток 15","A: занято 30, избыток 15; B: занято 40, избыток 30"],"options_uz":["A: bandlik 45, ortiqcha 15 soat; B: bandlik 70, ortiqcha 30","A: bandlik 30, ortiqcha yo‘q; B: bandlik 40, ortiqcha yo‘q","A: bandlik 30, ortiqcha 30; B: bandlik 40, ortiqcha 15","A: bandlik 30, ortiqcha 15; B: bandlik 40, ortiqcha 30"],"why":["At w=25, A labour demand is 80−50=30 and supply is 45, giving 15 excess hours. B demand is 140−100=40 and supply is 70, giving 30 excess. Each market''s unconstrained equilibrium wage was $20, so the floor binds.","При w=25 спрос A равен 30, предложение 45, избыточное предложение 15. В B спрос 40, предложение 70, избыток 30. До закона в обоих рынках равновесная ставка $20, поэтому минимум обязателен.","w=25 da A talab 30, taklif 45, ortiqcha 15. B talab 40, taklif 70, ortiqcha 30. Dastlab ikkala bozorning muvozanat ish haqi $20, shuning uchun $25 cheklovchi minimum."]},{"ref":"EC9708:G2:EC9708-G2-T5-T-013","d":"hard","sec":135,"k":"B","en":"A school has exactly 60 extra tutoring hours. Thirty pupils in Group Y need one hour each to reach the minimum standard, while twenty pupils in Group X need two hours each. A pupil reaches the standard only after receiving their full requirement. If the sole stated objective is to maximise the number who reach the standard, which allocation succeeds, and what important limitation should be acknowledged?","ru":"У школы ровно 60 часов дополнительных занятий. Тридцати ученикам группы Y требуется по одному часу, а двадцати ученикам группы X — по два часа для достижения минимального стандарта. Результат достигается лишь после получения всей необходимой помощи. Если заявленная единственная цель — максимальное число достигших стандарта, какое распределение оптимально и какое ограничение оценки важно признать?","uz":"Maktabda aynan 60 ta qo‘shimcha dars soati bor. Y guruhidagi 30 o‘quvchining har biriga standartga yetish uchun 1 soat, X guruhidagi 20 o‘quvchining har biriga 2 soat kerak. O‘quvchi talab qilingan barcha soatni olsagina standartga yetadi. Maqsad faqat standartga yetganlar sonini oshirish bo‘lsa, qaysi taqsimot optimal va qanday cheklovni e’tirof etish zarur?","options_en":["Give 1.2 hours to every pupil; all 50 reach the standard and fairness is guaranteed","Give 30 hours to all Y pupils and 30 hours to 15 X pupils; 45 reach the standard, but that does not by itself prove the allocation is the fairest","Give 40 hours to X and the remaining 20 hours to Y; all 50 reach the standard","Give the full 60 hours to 20 X pupils; 50 reach the standard"],"options_ru":["Дать каждому по 1,2 часа; все 50 достигнут стандарта, справедливость гарантирована","Дать 30 часов всем Y и 30 часов 15 ученикам X; стандарт достигнут 45, но это не доказывает максимальную справедливость","Дать 40 часов X и 20 часов Y; все 50 достигнут стандарта","Отдать все 60 часов двадцати ученикам X; стандарт достигнут 50"],"options_uz":["Hammaga 1,2 soatdan berish; 50 nafarning barchasi standartga yetadi va adolat kafolatlanadi","Y dagi barchaga 30 soat, X dagi 15 kishiga 30 soat; 45 kishi standartga yetadi, ammo bu eng adolatli taqsimot ekanini isbotlamaydi","X ga 40 soat, Y ga 20 soat; 50 kishi standartga yetadi","60 soatning hammasini X dagi 20 kishiga berish; 50 kishi standartga yetadi"],"why":["Complete all 30 one-hour Y requirements (30 hours), then 15 two-hour X requirements (30 hours), reaching 45 pupils. Giving X priority yields only 40 completed pupils. Maximising a count is not identical to meeting a broader equity objective.","Сначала закрываются потребности всех 30 учеников Y (30 часов), затем 15 учеников X (ещё 30 часов): всего 45. При приоритете X можно довести до стандарта только 40. Максимизация числа результатов не равнозначна общей справедливости.","Avval Y dagi 30 kishiga 30 soat, keyin X dagi 15 kishiga 30 soat beriladi; jami 45 kishi yetadi. X ni ustun qo‘yish faqat 40 natija beradi. Soni ko‘pligi har tomonlama adolatni anglatmaydi."]},{"ref":"EC9708:G2:EC9708-G2-T5-T-014","d":"hard","sec":135,"k":"C","en":"A regulated fish market has inverse demand P=100−0.5Q and competitive marginal supply cost MC=20+0.25Q. A binding quota limits catches to 80 fish. A single licence holder buys all 80 fish at one uniform price equal to MC at Q=80 and resells them at the market demand price. What are the resale price and total gross scarcity rent for that holder, ignoring all other costs?","ru":"На рыбном рынке обратный спрос P=100−0,5Q, конкурентные предельные затраты предложения MC=20+0,25Q. Обязательная квота ограничивает вылов 80 рыбами. Один владелец лицензии покупает все 80 рыб по единой цене, равной MC при Q=80, и перепродаёт по рыночной цене спроса. Какова цена перепродажи и общая валовая дефицитная рента владельца лицензии без учёта иных затрат?","uz":"Baliq bozorida teskari talab P=100−0,5Q, raqobatli chegaraviy taklif xarajati MC=20+0,25Q. Majburiy kvota ovni 80 dona bilan cheklaydi. Bitta litsenziya egasi 80 baliqning barchasini Q=80 dagi MC ga teng yagona narxda olib, bozor talab narxida qayta sotadi. Boshqa xarajatsiz qayta sotish narxi va egasining jami yalpi tanqislik rentasi qancha?","options_en":["Price $40; rent $1,600","Price $60; rent $800","Price $60; rent $1,600","Price $80; rent $3,200"],"options_ru":["Цена $40; доход лицензии $1 600","Цена $60; доход лицензии $800","Цена $60; доход лицензии $1 600","Цена $80; доход лицензии $3 200"],"options_uz":["Narx $40; litsenziya rentasi $1600","Narx $60; litsenziya rentasi $800","Narx $60; litsenziya rentasi $1600","Narx $80; litsenziya rentasi $3200"],"why":["At Q=80 the uniform purchase price is MC=20+0.25×80=$40, while the market selling price is P=100−0.5×80=$60. The licence holder''s gross rent is (60−40)×80=$1,600, given the explicitly uniform purchase price.","При Q=80 единая цена покупки MC=20+0,25×80=$40, цена продажи по спросу P=100−0,5×80=$60. Валовая рента владельца лицензии ($60−$40)×80=$1 600 при условии единой закупочной цены.","Q=80 da yagona xarid narxi MC=20+0,25×80=$40, talab bo‘yicha sotuv narxi P=100−0,5×80=$60. Bir xil xarid narxi shartida litsenziya egasining yalpi rentasi ($60−$40)×80=$1600."]},{"ref":"EC9708:G2:EC9708-G2-T5-T-019","d":"hard","sec":135,"k":"A","en":"Before reform, 200 small bakeries each pay an annual permit fee of $500 to the government. Processing these permits also consumes $35,000 in real public administrative resources and $15,000 in real business preparation costs each year. The government abolishes the permit and related paperwork but retains identical food-safety inspections. Assume no change in the number of bakeries or other effects. What is the net annual social RESOURCE saving, and how should the lost fee revenue be treated?","ru":"До реформы 200 небольших пекарен ежегодно платят государству по $500 за разрешение. Оформление разрешений также потребляет $35 000 реальных государственных административных ресурсов и $15 000 реальных затрат бизнеса на подготовку документов. Разрешение и оформление отменяются, проверки пищевой безопасности остаются прежними. Число пекарен и прочие условия не меняются. Какова годовая экономия реальных ресурсов общества и как учитывать исчезнувшие поступления от сборов?","uz":"Islohotdan oldin 200 ta kichik nonvoyxona davlatga har yili $500 litsenziya to‘lovi qiladi. Ruxsatnomani ko‘rib chiqish uchun $35 000 real davlat boshqaruv resursi va $15 000 biznes hujjat xarajati ketadi. Ruxsatnoma va qog‘ozbozlik bekor qilinadi, oziq-ovqat xavfsizligi tekshiruvlari o‘zgarmaydi. Nonvoyxonalar soni va boshqa sharoit o‘zgarmaydi. Jamiyatning yillik real resurs tejami qancha va yo‘qolgan yig‘im tushumiga qanday qaraladi?","options_en":["$50,000; lost $100,000 fees are transfers, not resource costs","$150,000; fee revenue and administration are both real resource costs","−$50,000; losing fees always makes deregulation socially harmful","$100,000; the administrative and paperwork resources have no value"],"options_ru":["$50 000; исчезнувшие $100 000 сборов — трансферт, а не реальные затраты ресурсов","$150 000; сборы и администрирование одинаково являются расходами ресурсов","−$50 000; потеря сборов всегда делает реформу общественно вредной","$100 000; ресурсы на администрирование и документы ничего не стоят"],"options_uz":["$50 000; yo‘qolgan $100 000 yig‘im transfert, real resurs xarajati emas","$150 000; yig‘im va boshqaruv ikkalasi ham real resurs sarfi","−$50 000; yig‘im yo‘qolishi tartibni bekor qilishni doim zararli qiladi","$100 000; boshqaruv va hujjat resurslari qiymatsiz"],"why":["Real resources saved are $35,000 public administration plus $15,000 business paperwork=$50,000. The $500×200=$100,000 fees move money from firms to government; eliminating them reverses a transfer, not a social resource cost under these assumptions.","Реальная экономия — $35 000 на госадминистрировании плюс $15 000 на документах бизнеса, всего $50 000. Сборы $500×200=$100 000 были перечислением денег от фирм государству, не потреблением ресурсов.","Real tejam $35 000 davlat boshqaruvi va $15 000 biznes hujjati, jami $50 000. $500×200=$100 000 yig‘im firma va davlat o‘rtasidagi transfert bo‘lib, real resurs sarfi emas."]}]'::jsonb;
 x jsonb; oldq record; new_id bigint; i int; idx int; keytxt text; reftext text; cnt int;
 enwhy text; ruwhy text; uzwhy text; ez int; med int; hard int;
BEGIN
 IF jsonb_array_length(d)<>4 THEN RAISE EXCEPTION 'T5_four_hard_required'; END IF;
 IF EXISTS(SELECT 1 FROM public.tour_attempts at JOIN public.tours t ON t.id=at.tour_id WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=5)
 THEN RAISE EXCEPTION 'T5_season2_attempts_exist'; END IF;
 SELECT count(*) INTO cnt FROM public.tours t JOIN public.tour_questions l ON l.tour_id=t.id AND l.is_active
 WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=5;
 IF cnt<>20 THEN RAISE EXCEPTION 'T5_pool_not20_before: %',cnt; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(d) LOOP
   reftext:=x->>'ref';keytxt:=x->>'k';idx:=ascii(keytxt)-65;
   IF keytxt NOT IN ('A','B','C','D') OR x->>'d'<>'hard'
      OR jsonb_array_length(x->'options_en')<>4 OR jsonb_array_length(x->'options_ru')<>4
      OR jsonb_array_length(x->'options_uz')<>4
   THEN RAISE EXCEPTION 'T5_invalid_authoring: %',reftext; END IF;
   SELECT q.id,q.subject_id,q.topic,q.subtopic,q.quality_flag,l.tour_id,l.order_no
   INTO STRICT oldq FROM public.questions q JOIN public.tour_questions l ON l.question_id=q.id AND l.is_active
   JOIN public.tours t ON t.id=l.tour_id
   WHERE q.subject_id=7 AND t.subject_id=7 AND t.season_id=2 AND t.tour_no=5 AND q.book_ref=reftext;
   IF EXISTS(SELECT 1 FROM public.tour_answers a WHERE a.question_id=oldq.id)
      OR EXISTS(SELECT 1 FROM public.tour_session_answers_v4 a WHERE a.question_id=oldq.id)
      OR EXISTS(SELECT 1 FROM public.questions q WHERE q.subject_id=7 AND q.book_ref=reftext||'-V2')
   THEN RAISE EXCEPTION 'T5_history_or_duplicate: %',reftext; END IF;
   enwhy:=x->'why'->>0;ruwhy:=x->'why'->>1;uzwhy:=x->'why'->>2;
   INSERT INTO public.questions(subject_id,topic,subtopic,difficulty,qtype,question_text,options_text,correct_answer,explanation,image_url,is_active,
   question_text_ru,question_text_uz,question_text_en,options_text_ru,options_text_uz,options_text_en,explanation_ru,explanation_uz,explanation_en,book_ref,time_limit_sec,quality_flag,quality_status)
   VALUES(oldq.subject_id,oldq.topic,oldq.subtopic,'hard','mcq',x->>'en',(x->'options_en')::text,keytxt,
   'Correct: '||(x->'options_en'->>idx)||E'\n'||enwhy,NULL,true,
   x->>'ru',x->>'uz',x->>'en',(x->'options_ru')::text,(x->'options_uz')::text,(x->'options_en')::text,
   'Правильный ответ: '||(x->'options_ru'->>idx)||E'\n'||ruwhy,
   'To‘g‘ri javob: '||(x->'options_uz'->>idx)||E'\n'||uzwhy,
   'Correct answer: '||(x->'options_en'->>idx)||E'\n'||enwhy,
   reftext||'-V2',(x->>'sec')::int,oldq.quality_flag,'published')
   RETURNING id INTO new_id;
   UPDATE public.tour_questions SET is_active=false WHERE tour_id=oldq.tour_id AND question_id=oldq.id AND is_active;
   GET DIAGNOSTICS cnt=ROW_COUNT;
   IF cnt<>1 THEN RAISE EXCEPTION 'T5_old_link_count: %',reftext; END IF;
   INSERT INTO public.tour_questions(tour_id,question_id,order_no,is_active) VALUES(oldq.tour_id,new_id,oldq.order_no,true);
   INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason)
   VALUES(oldq.id,new_id,'replacement','Economics Gen2 season2 Tour5: actual high-order difficulty replacement; old question preserved');
   FOR i IN 0..3 LOOP
     INSERT INTO public.question_answer_diagnostics(question_id,answer_kind,answer_key,answer_value,is_correct,
        mistake_type,weak_skill,feedback_ru,feedback_uz,feedback_en,next_action_ru,next_action_uz,next_action_en,rule_json,quality_status)
     VALUES(new_id,'mcq_option',chr(65+i),NULL,i=idx,
        CASE WHEN i=idx THEN NULL ELSE 'multi_step_economic_reasoning' END,oldq.subtopic,
        'Выбрано: '||(x->'options_ru'->>i)||E'\n'||ruwhy||E'\nОтвет: '||(x->'options_ru'->>idx),
        'Tanlov: '||(x->'options_uz'->>i)||E'\n'||uzwhy||E'\nJavob: '||(x->'options_uz'->>idx),
        'Selected: '||(x->'options_en'->>i)||E'\n'||enwhy||E'\nCorrect: '||(x->'options_en'->>idx),
        CASE WHEN i=idx THEN NULL ELSE 'Перепроверьте каждый шаг.' END,
        CASE WHEN i=idx THEN NULL ELSE 'Har bir bosqichni tekshiring.' END,
        CASE WHEN i=idx THEN NULL ELSE 'Check each step.' END,
        jsonb_build_object('diagnostic_code','EC9708_G2_T5T'||substring(reftext from 'T-([0-9]{3})')||'_V2_'||chr(65+i)),
        'published');
   END LOOP;
 END LOOP;
 UPDATE public.questions q SET difficulty=
  CASE WHEN right(q.book_ref,3) IN ('002','004','006','007','010','017') THEN 'easy' ELSE 'medium' END
 WHERE q.subject_id=7 AND q.book_ref ~ '^EC9708:G2:EC9708-G2-T5-T-[0-9]{3}$'
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d) z WHERE z->>'ref'=q.book_ref);
 GET DIAGNOSTICS cnt=ROW_COUNT;
 IF cnt<>16 THEN RAISE EXCEPTION 'T5_unchanged_expected16: %',cnt; END IF;
 SELECT count(*),count(*) FILTER(WHERE q.difficulty='easy'),
 count(*) FILTER(WHERE q.difficulty='medium'),count(*) FILTER(WHERE q.difficulty='hard')
 INTO cnt,ez,med,hard
 FROM public.tours t JOIN public.tour_questions l ON l.tour_id=t.id AND l.is_active
 JOIN public.questions q ON q.id=l.question_id WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=5;
 IF cnt<>20 OR ez<>6 OR med<>10 OR hard<>4 THEN
 RAISE EXCEPTION 'T5_mix_invalid: %,%,%,%',cnt,ez,med,hard; END IF;
END $tour5$;
COMMIT;
